from pathlib import Path
import re


def replace_once(path, old, new, label):
    p=Path(path)
    s=p.read_text()
    if old not in s:
        raise SystemExit(f'missing anchor: {label}')
    p.write_text(s.replace(old,new,1))

p=Path('app.jsx')
s=p.read_text()

# 查找預設先進世界；世界內再依地圖進一步找地點／人物／魚。
if 'const [fishViewV4, setFishViewV4] = useState("items");' in s:
    s=s.replace('const [fishViewV4, setFishViewV4] = useState("items");','const [fishViewV4, setFishViewV4] = useState("world");',1)

anchor='''  const [worldRegionV70, setWorldRegionV70] = useState("town");\n  const [worldQueryV70, setWorldQueryV70] = useState("");\n  const [worldOpenV70, setWorldOpenV70] = useState("");'''
